// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
    }

    function testFuzz_property(uint256 feeAmount) public {
        // Choose a concrete ERC20 asset address; must be a contract so that
        // the `ERC20(asset).transfer(recipient, fees)` call succeeds.
        // Deploy a tiny ERC20-like contract that accepts transfers.
        MockERC20 token = new MockERC20();
        address asset = address(token);

        // Admissible: owner (this test) seeds the fee ledger with a fuzzed amount.
        // We cannot write to unclaimedFees directly (it has only a getter).
        // Instead we must drive c's normal flow that credits unclaimedFees.
        // The simplest credit path is via `fillOrder` with fee > 0; however
        // manipulating that requires complex order/signature setup. To keep
        // the test focused and robust, we instead rely on the fact that the
        // mutation is about zeroing after withdrawal: we can pre-seed by
        // performing an initial successful withdrawal of a known amount, but
        // that would only transfer 0. We need a non-zero ledger.
        //
        // Because unclaimedFees has no setter, we must reach a non-zero value
        // through c's own public flow. The only public flow that credits it is
        // `fillOrder` when `fee > 0`. Setting c.fee requires onlyOwner (this
        // contract is owner), and we can pick fee=1. Then a fillOrder with a
        // long order transfers premium from maker and credits feeAmount.
        //
        // However building a valid order requires a signature. We can sign
        // with a fresh key whose address is the maker. We also need baseAsset
        // to be our MockERC20 and the contract must hold enough tokens to
        // cover the fee later.
        //
        // This is involved but necessary to satisfy "route through public
        // entry" and to have a non-zero unclaimedFees. We implement it below.

        // Bound the seeded fee amount to a reasonable non-zero range.
        feeAmount = bound(feeAmount, 1, type(uint128).max);

        // Configure c: fee = 1 (0.1%) to credit a non-zero fee on fill.
        c.setFee(1);

        // Build a maker and sign an order.
        uint256 makerPk = 0xA11CE;
        address maker = vm.addr(makerPk);

        // Ensure maker has enough MockERC20 balance to pay premium.
        MockERC20(address(asset)).mint(maker, feeAmount * 1000);

        // Construct a long call order so that premium is paid from maker and
        // feeAmount = premium * fee / 1000 is credited to unclaimedFees.
        // We want feeAmount to equal the fuzzed value, so set premium = feeAmount * 1000.
        uint256 premium = feeAmount * 1000;

        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);
        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: maker,
            isCall: true,
            isLong: true,
            baseAsset: asset,
            strike: 1,
            premium: premium,
            duration: 1 days,
            expiration: block.timestamp + 1 days,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(makerPk, orderHash);
        bytes memory signature = abi.encodePacked(r, s, v);

        // Maker must approve c to pull premium.
        vm.prank(maker);
        MockERC20(address(asset)).approve(address(c), type(uint256).max);

        // Fill the order as the taker (this test). For a long call, the taker
        // receives the position and pays nothing except possibly floor tokens;
        // the maker pays premium to the taker. Fee is credited to unclaimedFees.
        c.fillOrder(order, signature, floorAssetTokenIds);

        uint256 seededFees = c.unclaimedFees(asset);
        assertTrue(seededFees > 0, "ledger should be seeded");

        // The contract now holds the fee amount in MockERC20.
        // Now call withdrawFees as the owner (this test is owner).
        c.withdrawFees(asset, address(0xDEAD));

        // Property: after a successful withdrawFees, the ledger is cleared.
        assertTrue(c.unclaimedFees(asset) == 0, "unclaimedFees must be zero after withdrawal");
    }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) {
            allowance[from][msg.sender] = allowed - amount;
        }
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
